allow:
Bash(powershell -NoProfile -Command '
$start = Get-Process | Select-Object Id, ProcessName
Write-Output "Baseline: $\($start.Count\) processes"
Write-Output "Watching for 60 seconds for new processes..."
Start-Sleep 60
$now = Get-Process | Select-Object Id, ProcessName
$new = $now | Where-Object { $_.Id -notin $start.Id }
if \($new.Count -gt 0\) {
    Write-Output "NEW PROCESSES DETECTED:"
    $new | ForEach-Object {
        $cmd = \(Get-CimInstance Win32_Process -Filter "ProcessId=$\($_.Id\)" -ErrorAction SilentlyContinue\).CommandLine
        Write-Output "  PID $\($_.Id\) | $\($_.ProcessName\) | $cmd"
    }
} else {
    Write-Output "NO NEW PROCESSES in 60 seconds. Machine is quiet."
}
')
